class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        char_index = {}
        left = 0
        max_len = 0
        get = char_index.get

        for right in range(len(s)):
            ch = s[right]
            prev = get(ch, -1)
            if prev >= left:
                left = prev + 1
            char_index[ch] = right
            curr_len = right - left + 1
            if curr_len > max_len:
                max_len = curr_len

        return max_len

class Solution:
    def findMedianSortedArrays(self, nums1: list[int], nums2: list[int]) -> float:
        # Ensure nums1 is the smaller array
        if len(nums1) > len(nums2):
            nums1, nums2 = nums2, nums1

        m = len(nums1)
        n = len(nums2)
        total = m + n
        half = total >> 1  # Bit shift instead of division

        left, right = 0, m

        while left <= right:
            i = (left + right) >> 1  # Bit shift instead of division
            j = half - i

            # Inline boundary checks to avoid function calls
            if i > 0:
                nums1_left = nums1[i - 1]
            else:
                nums1_left = float('-inf')

            if i < m:
                nums1_right = nums1[i]
            else:
                nums1_right = float('inf')

            if j > 0:
                nums2_left = nums2[j - 1]
            else:
                nums2_left = float('-inf')

            if j < n:
                nums2_right = nums2[j]
            else:
                nums2_right = float('inf')

            # Optimized partition check
            if nums1_left <= nums2_right and nums2_left <= nums1_right:
                if total & 1:  # Bitwise AND for odd check
                    # Return smaller of the two right values
                    return nums1_right if nums1_right < nums2_right else nums2_right
                else:
                    # Calculate median for even case
                    max_left = nums1_left if nums1_left > nums2_left else nums2_left
                    min_right = nums1_right if nums1_right < nums2_right else nums2_right
                    return (max_left + min_right) * 0.5  # Multiplication instead of division
            elif nums1_left > nums2_right:
                right = i - 1
            else:
                left = i + 1

        return 0.0

class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        m, n = len(s), len(p)

        # Use 1D DP array to save memory - only need previous row
        dp = [False] * (n + 1)
        dp[0] = True

        # Handle patterns like a*, a*b*, etc., that can match empty string
        for j in range(2, n + 1):
            if p[j - 1] == '*':
                dp[j] = dp[j - 2]

        for i in range(1, m + 1):
            # Keep track of previous row's dp[0] value
            prev = dp[0]
            dp[0] = False  # Empty pattern can't match non-empty string

            for j in range(1, n + 1):
                curr = dp[j]  # Save current value before updating

                if p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                    dp[j] = prev
                elif p[j - 1] == '*':
                    # Zero occurrences of the preceding element
                    dp[j] = dp[j - 2]
                    # One or more occurrences
                    if p[j - 2] == '.' or p[j - 2] == s[i - 1]:
                        dp[j] = dp[j] or curr
                else:
                    dp[j] = False

                prev = curr  # Update prev for next iteration

        return dp[n]

class Solution:
    def maxArea(self, height: list[int]) -> int:
        left, right = 0, len(height) - 1
        max_water = 0
        h = height

        while left < right:
            hl = h[left]
            hr = h[right]
            if hl < hr:
                area = (right - left) * hl
                left += 1
            else:
                area = (right - left) * hr
                right -= 1
            if area > max_water:
                max_water = area

        return max_water

class Solution:
    def generateParenthesis(self, n: int) -> list[str]:
        result = []

        def backtrack(current: str, open_count: int, close_count: int):
            # If we've used all n pairs, add to result
            if len(current) == 2 * n:
                result.append(current)
                return

            # We can add an opening parenthesis if we haven't used all n
            if open_count < n:
                backtrack(current + "(", open_count + 1, close_count)

            # We can add a closing parenthesis if there are unmatched opening ones
            if close_count < open_count:
                backtrack(current + ")", open_count, close_count + 1)

        backtrack("", 0, 0)
        return result


