class Solution:
    def divide(self, dividend: int, divisor: int) -> int:
        if dividend == -2147483648 and divisor == -1:
            return 2147483647

        negative = (dividend < 0) ^ (divisor < 0)
        dividend = -dividend if dividend < 0 else dividend
        divisor = -divisor if divisor < 0 else divisor

        quotient = 0
        while dividend >= divisor:
            shift = 0
            while dividend >= (divisor << (shift + 1)):
                shift += 1
            dividend -= divisor << shift
            quotient += 1 << shift

        if negative:
            quotient = -quotient

        return -2147483648 if quotient < -2147483648 else (2147483647 if quotient > 2147483647 else quotient)

class Solution:
    def nextPermutation(self, nums: list[int]) -> None:
        n = len(nums)
        i = n - 2

        # Find first decreasing element from right
        while i >= 0 and nums[i] >= nums[i + 1]:
            i -= 1

        if i >= 0:
            # Find element just larger than nums[i] from right
            j = n - 1
            while nums[j] <= nums[i]:
                j -= 1
            nums[i], nums[j] = nums[j], nums[i]

        # Reverse the suffix starting at i+1
        left, right = i + 1, n - 1
        while left < right:
            nums[left], nums[right] = nums[right], nums[left]
            left += 1
            right -= 1

