class Solution:
    def solveNQueens(self, n: int) -> List[List[str]]:
        if n == 1:
            return [["Q"]]

        res = []
        full_mask = (1 << n) - 1
        row_strs = ["." * c + "Q" + "." * (n - c - 1) for c in range(n)]

        # Precompute bit positions to avoid bit_length() calls
        bit_to_col = {1 << i: i for i in range(n)}

        def backtrack(r, cols, diag1, diag2, queens):
            if r == n:
                res.append([row_strs[c] for c in queens])
                return

            avail = full_mask & ~(cols | diag1 | diag2)
            while avail:
                bit = avail & -avail
                avail ^= bit
                queens[r] = bit_to_col[bit]
                backtrack(r + 1, cols | bit, (diag1 | bit) << 1, (diag2 | bit) >> 1, queens)

        backtrack(0, 0, 0, 0, [0] * n)
        return res

class Solution:
    def totalNQueens(self, n: int) -> int:
        if n == 1:
            return 1
        if n in (2, 3):
            return 0

        full = (1 << n) - 1

        def backtrack(cols, diag1, diag2):
            if cols == full:
                return 1
            count = 0
            available = full & ~(cols | diag1 | diag2)
            while available:
                bit = available & -available
                available ^= bit
                count += backtrack(
                    cols | bit,
                    ((diag1 | bit) << 1) & full,
                    (diag2 | bit) >> 1,
                )
            return count

        return backtrack(0, 0, 0)

class Solution:
    def canJump(self, nums: list[int]) -> bool:
        n = len(nums)
        if n == 1:
            return True
        target = n - 1
        max_reach = 0
        for i in range(n - 1):
            jump = nums[i]
            reach = i + jump
            if reach > max_reach:
                max_reach = reach
                if max_reach >= target:
                    return True
            elif i >= max_reach:
                return False
        return max_reach >= target

class Solution:
    def uniquePaths(self, m: int, n: int) -> int:
        # Use the smaller dimension for the DP array to minimize memory
        if m > n:
            m, n = n, m

        # row[j] represents the number of paths to reach column j in the current row
        row = [1] * m

        # Iterate over rows (n-1 additional rows beyond the first)
        for _ in range(1, n):
            # Update in-place: row[j] = row[j] (from above) + row[j-1] (from left)
            for j in range(1, m):
                row[j] += row[j - 1]

        return row[-1]

class Solution:
    def uniquePathsWithObstacles(self, obstacleGrid: list[list[int]]) -> int:
        m, n = len(obstacleGrid), len(obstacleGrid[0])

        if obstacleGrid[0][0] == 1 or obstacleGrid[m-1][n-1] == 1:
            return 0

        dp = [0] * n
        dp[0] = 1

        for i in range(m):
            row = obstacleGrid[i]
            # Handle first column: if obstacle, dp[0] becomes 0 and stays 0
            if row[0] == 1:
                dp[0] = 0
            # Process remaining columns
            for j in range(1, n):
                if row[j] == 1:
                    dp[j] = 0
                else:
                    dp[j] += dp[j-1]

        return dp[n-1]

class Solution:
    def minPathSum(self, grid: list[list[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Handle edge cases
        if m == 1:
            return sum(grid[0])
        if n == 1:
            return sum(row[0] for row in grid)

        # Initialize dp with first row cumulative sums
        dp = grid[0][:]
        for j in range(1, n):
            dp[j] += dp[j - 1]

        # Process remaining rows
        for i in range(1, m):
            row = grid[i]
            dp[0] += row[0]
            for j in range(1, n):
                dp[j] = row[j] + min(dp[j], dp[j - 1])

        return dp[-1]

