class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        # Handle empty strings
        if not word1:
            return len(word2)
        if not word2:
            return len(word1)

        # Remove common prefix
        start = 0
        len1, len2 = len(word1), len(word2)
        while start < len1 and start < len2 and word1[start] == word2[start]:
            start += 1
        word1 = word1[start:]
        word2 = word2[start:]

        # Remove common suffix
        end1, end2 = len(word1), len(word2)
        while end1 > 0 and end2 > 0 and word1[end1 - 1] == word2[end2 - 1]:
            end1 -= 1
            end2 -= 1
        word1 = word1[:end1]
        word2 = word2[:end2]

        # Handle cases after trimming
        if not word1:
            return len(word2)
        if not word2:
            return len(word1)

        # Ensure word2 is the shorter string for space optimization
        if len(word1) < len(word2):
            word1, word2 = word2, word1

        m, n = len(word1), len(word2)

        # Pre-allocate two rows and swap them to avoid repeated allocation
        prev = list(range(n + 1))
        curr = [0] * (n + 1)

        for i in range(1, m + 1):
            curr[0] = i
            c1 = word1[i - 1]
            for j in range(1, n + 1):
                if c1 == word2[j - 1]:
                    curr[j] = prev[j - 1]
                else:
                    # Inline min of three values for speed
                    a = prev[j - 1]
                    b = prev[j]
                    c = curr[j - 1]
                    if b < a:
                        a = b
                    if c < a:
                        a = c
                    curr[j] = a + 1
            prev, curr = curr, prev

        return prev[n]

class Solution:
    def searchMatrix(self, matrix: List[List[int]], target: int) -> bool:
        m = len(matrix)
        n = len(matrix[0])
        left, right = 0, m * n - 1

        while left <= right:
            mid = (left + right) >> 1
            row = mid // n
            mid_val = matrix[row][mid - row * n]

            if mid_val == target:
                return True
            if mid_val < target:
                left = mid + 1
            else:
                right = mid - 1

        return False

