class Solution:
    def deleteDuplicates(self, head: ListNode) -> ListNode:
        dummy = ListNode(0, head)
        prev = dummy
        curr = head

        while curr:
            nxt = curr.next
            if nxt and curr.val == nxt.val:
                val = curr.val
                while nxt and nxt.val == val:
                    nxt = nxt.next
                prev.next = nxt
                curr = nxt
            else:
                prev = curr
                curr = nxt

        return dummy.next

