class Solution:
    def maximalRectangle(self, matrix: List[List[str]]) -> int:
        if not matrix or not matrix[0]:
            return 0

        cols = len(matrix[0])
        heights = [0] * cols
        max_area = 0

        for row in matrix:
            stack = []
            for i in range(cols):
                heights[i] = heights[i] + 1 if row[i] == '1' else 0
                h = heights[i]
                while stack and heights[stack[-1]] > h:
                    height = heights[stack.pop()]
                    width = i if not stack else i - stack[-1] - 1
                    area = height * width
                    if area > max_area:
                        max_area = area
                stack.append(i)

            # Process remaining stack with sentinel height 0 at position cols
            while stack:
                height = heights[stack.pop()]
                width = cols if not stack else cols - stack[-1] - 1
                area = height * width
                if area > max_area:
                    max_area = area

        return max_area

class Solution:
    def isScramble(self, s1: str, s2: str) -> bool:
        memo = {}

        def dfs(a: str, b: str) -> bool:
            if a == b:
                return True
            if len(a) != len(b) or sorted(a) != sorted(b):
                return False
            if (a, b) in memo:
                return memo[(a, b)]

            n = len(a)
            for i in range(1, n):
                # No swap
                if dfs(a[:i], b[:i]) and dfs(a[i:], b[i:]):
                    memo[(a, b)] = True
                    return True
                # Swap
                if dfs(a[:i], b[n-i:]) and dfs(a[i:], b[:n-i]):
                    memo[(a, b)] = True
                    return True

            memo[(a, b)] = False
            return False

        return dfs(s1, s2)

