class Solution:
    def restoreIpAddresses(self, s: str) -> list[str]:
        n = len(s)
        result = []

        # Early exit: valid IP needs 4-12 digits
        if n < 4 or n > 12:
            return result

        # Precompute digit values to avoid repeated ord() calls
        digits = [ord(c) - 48 for c in s]
        parts = []

        def backtrack(start: int, part_idx: int):
            remaining = n - start
            remaining_parts = 4 - part_idx
            # Pruning: remaining chars must fit remaining parts (1-3 digits each)
            if remaining < remaining_parts or remaining > remaining_parts * 3:
                return

            if part_idx == 3:
                # Last part: must consume all remaining chars (1-3 digits)
                if remaining > 3:
                    return
                if remaining > 1 and digits[start] == 0:
                    return
                val = 0
                for i in range(start, n):
                    val = val * 10 + digits[i]
                if val <= 255:
                    parts.append(s[start:])
                    result.append('.'.join(parts))
                    parts.pop()
                return

            val = 0
            end = start + 3 if start + 3 < n else n
            for i in range(start, end):
                val = val * 10 + digits[i]
                if val > 255:
                    break
                if i > start and digits[start] == 0:
                    break
                parts.append(s[start:i+1])
                backtrack(i + 1, part_idx + 1)
                parts.pop()

        backtrack(0, 0)
        return result

class Solution:
    def numTrees(self, n: int) -> int:
        # Catalan number: C(n) = C(n-1) * 2*(2n-1) / (n+1)
        result = 1
        for i in range(1, n + 1):
            result = result * 2 * (2 * i - 1) // (i + 1)
        return result

class Solution:
    def isInterleave(self, s1: str, s2: str, s3: str) -> bool:
        m, n = len(s1), len(s2)
        if m + n != len(s3):
            return False

        dp = [False] * (n + 1)
        dp[0] = True

        # Initialize first row (using only s2)
        for j in range(1, n + 1):
            dp[j] = dp[j - 1] and s2[j - 1] == s3[j - 1]

        for i in range(1, m + 1):
            dp[0] = dp[0] and s1[i - 1] == s3[i - 1]
            for j in range(1, n + 1):
                dp[j] = (dp[j] and s1[i - 1] == s3[i + j - 1]) or \
                        (dp[j - 1] and s2[j - 1] == s3[i + j - 1])

        return dp[n]

