class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

    @staticmethod
    def deserialize(data):
        if not data:
            return None
        root = TreeNode(data[0])
        queue = deque([root])
        i = 1
        n = len(data)
        while queue and i < n:
            node = queue.popleft()
            if data[i] is not None:
                node.left = TreeNode(data[i])
                queue.append(node.left)
            i += 1
            if i < n and data[i] is not None:
                node.right = TreeNode(data[i])
                queue.append(node.right)
            i += 1
        return root

class Solution:
    def isBalanced(self, root: TreeNode) -> bool:
        # Returns height if balanced, -1 if unbalanced (early termination)
        def check(node):
            if node is None:
                return 0
            left = check(node.left)
            if left == -1:
                return -1
            right = check(node.right)
            if right == -1:
                return -1
            if abs(left - right) > 1:
                return -1
            return (left if left > right else right) + 1

        return check(root) != -1

