        if not root:
            return []

        result = []
        path = []

        def dfs(node, remaining_sum):
            path.append(node.val)
            remaining_sum -= node.val

            # Check if it's a leaf
            if not node.left and not node.right:
                if remaining_sum == 0:
                    result.append(path.copy())
            else:
