class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        m, n = len(s), len(t)

        # Early termination
        if n > m:
            return 0

        # Precompute positions of each character in t (1-indexed for DP)
        # This avoids checking every j position for each character
        char_positions = {}
        for j, c in enumerate(t, 1):
            if c not in char_positions:
                char_positions[c] = []
            char_positions[c].append(j)

        # Quick check: ensure all characters in t exist in s
        s_chars = set(s)
        for c in char_positions:
            if c not in s_chars:
                return 0

        # 1D DP array
        dp = [0] * (n + 1)
        dp[0] = 1

        # Process each character in s
        for char in s:
            # Only process if character exists in t
            if char in char_positions:
                # Traverse backwards through only relevant positions
                for j in reversed(char_positions[char]):
                    dp[j] += dp[j - 1]

        return dp[n]

