class Solution:
    def findLadders(self, beginWord: str, endWord: str, wordList: list[str]) -> list[list[str]]:
        if endWord not in wordList:
            return []

        wordSet = set(wordList)
        n = len(beginWord)
        letters = 'abcdefghijklmnopqrstuvwxyz'

        # BFS to build distance map and parents
        layer = {beginWord: 0}
        parents = defaultdict(list)
        queue = deque([beginWord])
        found = False
        step = 0

        while queue and not found:
            step += 1
            layer_size = len(queue)

            for _ in range(layer_size):
                word = queue.popleft()

                # Generate neighbors more efficiently
                for i in range(n):
                    prefix = word[:i]
                    suffix = word[i+1:]
                    original_char = word[i]

                    for c in letters:
                        if c == original_char:
                            continue
                        new_word = prefix + c + suffix

                        if new_word in wordSet:
                            if new_word not in layer:
                                layer[new_word] = step
                                queue.append(new_word)
                                parents[new_word].append(word)
                            elif layer[new_word] == step:
                                parents[new_word].append(word)

            # Check if we found endWord in this layer
            if endWord in layer and layer[endWord] == step:
                found = True

        # DFS to build all shortest paths - iterative approach
        if endWord not in layer:
            return []

        res = []

        def dfs(word, path):
            if word == beginWord:
                res.append(path[::-1])
                return

            for p in parents[word]:
                path.append(p)
                dfs(p, path)
                path.pop()

        dfs(endWord, [endWord])
        return res

