class Solution:
    def hasCycle(self, head, pos=-1):
        # If head is a list, construct the linked list
        if isinstance(head, list):
            n = len(head)
            if n == 0:
                return False

            # Build nodes and connect in one pass
            nodes = [None] * n
            prev = None
            for i in range(n):
                node = ListNode(head[i])
                nodes[i] = node
                if prev is not None:
                    prev.next = node
                prev = node

            # Create cycle if pos is valid
            if 0 <= pos < n:
                prev.next = nodes[pos]

            head = nodes[0]

        # Floyd's cycle detection algorithm
        if head is None or head.next is None:
            return False

        slow = head
        fast = head.next

        while slow is not fast:
            if fast is None or fast.next is None:
                return False
            slow = slow.next
            fast = fast.next.next

        return True

