class Solution:
    def maximumGap(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 2:
            return 0

        min_val = max_val = nums[0]
        for num in nums:
            if num < min_val:
                min_val = num
            if num > max_val:
                max_val = num

        if min_val == max_val:
            return 0

        bucket_count = n - 1
        span = max_val - min_val

        bucket_min = [None] * bucket_count
        bucket_max = [None] * bucket_count

        for num in nums:
            if num == min_val or num == max_val:
                continue
            idx = (num - min_val) * bucket_count // span
            if idx >= bucket_count:
                idx = bucket_count - 1
            bmin = bucket_min[idx]
            if bmin is None:
                bucket_min[idx] = num
                bucket_max[idx] = num
            else:
                if num < bmin:
                    bucket_min[idx] = num
                elif num > bucket_max[idx]:
                    bucket_max[idx] = num

        max_gap = 0
        prev_max = min_val

        for i in range(bucket_count):
            bmin = bucket_min[i]
            if bmin is None:
                continue
            gap = bmin - prev_max
            if gap > max_gap:
                max_gap = gap
            prev_max = bucket_max[i]

        gap = max_val - prev_max
        if gap > max_gap:
            max_gap = gap

        return max_gap

