        # Phase 1: Find potential candidates using Boyer-Moore algorithm
        candidate1 = candidate2 = None
        count1 = count2 = 0

        for num in nums:
            if candidate1 == num:
                count1 += 1
            elif candidate2 == num:
                count2 += 1
            elif count1 == 0:
                candidate1 = num
                count1 = 1
            elif count2 == 0:
                candidate2 = num
                count2 = 1
            else:
                count1 -= 1
                count2 -= 1

        # Phase 2: Verify candidates and build result in one pass
        threshold = n // 3
        count1 = count2 = 0
        result = []

        for num in nums:
            if num == candidate1:
                count1 += 1
                if count1 == threshold + 1:  # Found majority element
                    result.append(candidate1)
            elif num == candidate2:
                count2 += 1
                if count2 == threshold + 1:  # Found majority element
                    result.append(candidate2)

        return result

class Solution:
    def countDigitOne(self, n: int) -> int:
        if n <= 0:
            return 0

        count = 0
        place = 1

        while place <= n:
            higher = n // (place * 10)
            current = (n // place) % 10
            lower = n % place

            if current == 0:
                count += higher * place
            elif current == 1:
                count += higher * place + lower + 1
            else:
                count += (higher + 1) * place

            place *= 10

        return count

class Solution:
    def isAnagram(self, s: str, t: str) -> bool:
        if len(s) != len(t):
            return False
        return sorted(s) == sorted(t)

class Solution:
    def isStrobogrammatic(self, num: str) -> bool:
        pairs = {'0': '0', '1': '1', '6': '9', '8': '8', '9': '6'}
        left, right = 0, len(num) - 1
        while left <= right:
            l = num[left]
            if l not in pairs or pairs[l] != num[right]:
                return False
            left += 1
            right -= 1
        return True
